<div class="page-heading d-flex justify-content-between align-items-end gap-3 flex-wrap"><div><p class="eyebrow">Browse documentation</p><h1><?= e($title) ?></h1><p><?= count($articles) ?> records match the current view.</p></div><?php if (has_role('Admin','Editor')): ?><a class="btn btn-primary" href="/admin/articles/create"><i class="bi bi-plus-lg"></i> New article</a><?php endif; ?></div>
<form class="filter-bar" method="get">
    <?php if (!$fixedType): ?><select class="form-select" name="type"><option value="">All types</option><?php foreach (['Article','Error','SOP','Request'] as $v): ?><option <?= ($_GET['type'] ?? '') === $v ? 'selected' : '' ?>><?= $v ?></option><?php endforeach; ?></select><?php endif; ?>
    <select class="form-select" name="system_id"><option value="">All systems</option><?php foreach ($systems as $item): ?><option value="<?= $item['id'] ?>" <?= (string)($_GET['system_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select>
    <select class="form-select" name="category_id"><option value="">All categories</option><?php foreach ($categories as $item): ?><option value="<?= $item['id'] ?>" <?= (string)($_GET['category_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select>
    <select class="form-select" name="carrier_id"><option value="">All carriers</option><?php foreach ($carriers as $item): ?><option value="<?= $item['id'] ?>" <?= (string)($_GET['carrier_id'] ?? '') === (string)$item['id'] ? 'selected' : '' ?>><?= e($item['name']) ?></option><?php endforeach; ?></select>
    <select class="form-select" name="severity"><option value="">All severities</option><?php foreach (['Critical','High','Medium','Low'] as $v): ?><option <?= ($_GET['severity'] ?? '') === $v ? 'selected' : '' ?>><?= $v ?></option><?php endforeach; ?></select>
    <?php if (has_role('Admin','Editor')): ?><select class="form-select" name="status"><option value="">All statuses</option><?php foreach (['Draft','Published','Under Review','Archived'] as $v): ?><option <?= ($_GET['status'] ?? '') === $v ? 'selected' : '' ?>><?= $v ?></option><?php endforeach; ?></select><?php endif; ?>
    <select class="form-select" name="updated"><option value="">Any update date</option><option value="7" <?= ($_GET['updated'] ?? '') === '7' ? 'selected' : '' ?>>Last 7 days</option><option value="30" <?= ($_GET['updated'] ?? '') === '30' ? 'selected' : '' ?>>Last 30 days</option><option value="90" <?= ($_GET['updated'] ?? '') === '90' ? 'selected' : '' ?>>Last 90 days</option></select>
    <button class="btn btn-primary"><i class="bi bi-funnel"></i> Apply</button><a class="btn btn-outline-secondary" href="<?= e(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH)) ?>" title="Clear filters"><i class="bi bi-x-lg"></i></a>
</form>
<?php if (!$articles): ?><div class="empty-state"><i class="bi bi-journal-x"></i><h2>No matching documentation</h2><p>Clear one or more filters to widen the result set.</p></div><?php else: ?><div class="browse-grid"><?php foreach ($articles as $article): ?><a class="browse-card" href="/articles/<?= $article['id'] ?>"><div class="d-flex justify-content-between gap-2"><span class="type-icon"><i class="bi <?= article_icon($article['type']) ?>"></i></span><div><?php if ($article['severity']): ?><span class="badge <?= severity_class($article['severity']) ?>"><?= e($article['severity']) ?></span><?php endif; ?><?php if (has_role('Admin','Editor')): ?><span class="badge text-bg-light border"><?= e($article['status']) ?></span><?php endif; ?></div></div><div><span class="eyebrow"><?= e($article['type']) ?><?= $article['error_code'] ? ' · ' . e($article['error_code']) : '' ?></span><h2><?= e($article['title']) ?></h2><p><?= e($article['description']) ?></p></div><div class="metadata"><span><i class="bi bi-hdd-stack"></i><?= e($article['system_name'] ?? 'General') ?></span><?php if ($article['carrier_name']): ?><span><i class="bi bi-truck"></i><?= e($article['carrier_name']) ?></span><?php endif; ?><span class="ms-auto"><?= date('M j, Y', strtotime($article['updated_at'])) ?></span></div></a><?php endforeach; ?></div><?php endif; ?>
